-- GENERATED by `python -m aws.contract.render_ddl` from aws/contract/contract.json (5a6a18eefb0f6ecb). Do not edit.

-- The five analyses, ported from aws/athena/01-05_*.sql with REDSHIFT_REWRITES (render_ddl.py).
-- Each block starts with '-- name: <query>' so scripts can run them one at a time.
-- Prerequisite: aws/redshift/views.sql (gl.v_flow_panel).

-- name: 01_month_over_month
-- 01_month_over_month.sql  (Redshift)
-- Month-over-month change of the Central Secretariat aggregate: grievances received and month-end pending.
-- Port of analysis A (src/analysis/analyses.py):
--   * values from months with only a partial (pre-cut-off) figure are masked before differencing;
--   * the percentage is shown only when the previous month is at least 100 (MIN_BASE_FOR_PCT_CHANGE).
-- Self-check: pending_change must equal the published overall_trend.pending_change on every row.
WITH monthly AS (
    SELECT month,
           receipts,
           pending,
           has_partial_value,
           pending_change AS published_pending_change,
           pending_change_pct AS published_pending_change_pct,
           CASE WHEN has_partial_value THEN NULL ELSE receipts END AS receipts_complete,
           CASE WHEN has_partial_value THEN NULL ELSE pending END AS pending_complete
    FROM gl.overall_trend
),
lagged AS (
    SELECT m.*,
           LAG(receipts_complete) OVER (ORDER BY month) AS receipts_prev,
           LAG(pending_complete) OVER (ORDER BY month) AS pending_prev
    FROM monthly m
),
changes AS (
    SELECT month,
           has_partial_value,
           receipts,
           receipts_prev,
           receipts_complete - receipts_prev AS receipts_mom_change,
           CASE WHEN receipts_prev >= 100
                THEN 100 * CAST(receipts_complete - receipts_prev AS DOUBLE PRECISION) / receipts_prev END AS receipts_mom_pct,
           pending,
           pending_prev,
           pending_complete - pending_prev AS pending_change,
           CASE WHEN pending_prev >= 100
                THEN 100 * CAST(pending_complete - pending_prev AS DOUBLE PRECISION) / pending_prev END AS pending_change_pct,
           published_pending_change,
           published_pending_change_pct
    FROM lagged
)
SELECT month,
       has_partial_value,
       receipts,
       receipts_prev,
       receipts_mom_change,
       receipts_mom_pct,
       pending,
       pending_prev,
       pending_change,
       pending_change_pct,
       (pending_change = published_pending_change
        OR (pending_change IS NULL AND published_pending_change IS NULL)) AS matches_published
FROM changes
ORDER BY month;

-- name: 02_ministry_backlog
-- 02_ministry_backlog.sql  (Redshift)
-- Ministry backlog ranking: backlog_months = mean month-end pending / mean monthly receipts over the
-- single-month flow window (#29-#45), i.e. months of intake waiting. Size-neutral, unlike raw pending.
-- Port of src/export/powerbi.py _backlog_growth and the scorecard component: a ministry needs at least
-- 15 reports in the window (MIN_POINTS_DEMAND_BACKLOG) and positive mean receipts.
-- Ranked overall and within its 2026 GRAI volume group (A >= 500 grievances, B fewer), 1 = largest backlog.
-- Self-check: backlog_months must equal the published backlog_growth.backlog_months.
WITH per_ministry AS (
    SELECT ministry_id,
           COUNT(*) AS reports_in_window,
           AVG(CAST(pending AS DOUBLE PRECISION)) AS mean_pending,
           AVG(CAST(receipts AS DOUBLE PRECISION)) AS mean_monthly_receipts,
           MAX(CASE WHEN report_number = 45 THEN pending END) AS pending_latest
    FROM gl.v_flow_panel
    GROUP BY ministry_id
),
scored AS (
    SELECT p.*,
           CASE WHEN p.reports_in_window >= 15 AND p.mean_monthly_receipts > 0
                THEN p.mean_pending / p.mean_monthly_receipts END AS backlog_months
    FROM per_ministry p
)
SELECT s.ministry_id,
       d.canonical_name,
       d.grai_group_2026,
       s.reports_in_window,
       s.mean_monthly_receipts,
       s.mean_pending,
       s.pending_latest,
       s.backlog_months,
       RANK() OVER (ORDER BY s.backlog_months DESC) AS backlog_rank,
       RANK() OVER (PARTITION BY d.grai_group_2026 ORDER BY s.backlog_months DESC) AS backlog_rank_in_group,
       RANK() OVER (ORDER BY s.pending_latest DESC) AS pending_rank_latest,
       (ABS(s.backlog_months - b.backlog_months) < 1e-9
        OR (s.backlog_months IS NULL AND b.backlog_months IS NULL)) AS matches_published
FROM scored s
JOIN gl.dim_ministry d ON d.ministry_id = s.ministry_id
LEFT JOIN gl.backlog_growth b ON b.ministry_id = s.ministry_id
WHERE s.backlog_months IS NOT NULL
ORDER BY backlog_rank, s.ministry_id;

-- name: 03_rolling_average
-- 03_rolling_average.sql  (Redshift)
-- Rolling three-month means of receipts, disposals and month-end pending (Central Secretariat aggregate).
-- Port of analysis A: rolling(3, min_periods=3) over complete months only, so a window touching a month
-- with only a partial (pre-cut-off) value has no average rather than a distorted one.
-- overall_trend has one row per calendar month with no gaps (dim_month is continuous), so 2 PRECEDING
-- rows are exactly the two previous months.
-- Self-check: the three averages must equal the published *_roll3 columns.
WITH masked AS (
    SELECT month,
           has_partial_value,
           receipts_roll3 AS published_receipts_roll3,
           disposals_roll3 AS published_disposals_roll3,
           pending_roll3 AS published_pending_roll3,
           CASE WHEN has_partial_value THEN NULL ELSE CAST(receipts AS DOUBLE PRECISION) END AS receipts_c,
           CASE WHEN has_partial_value THEN NULL ELSE CAST(disposals AS DOUBLE PRECISION) END AS disposals_c,
           CASE WHEN has_partial_value THEN NULL ELSE CAST(pending AS DOUBLE PRECISION) END AS pending_c
    FROM gl.overall_trend
),
rolled AS (
    SELECT month,
           has_partial_value,
           CASE WHEN COUNT(receipts_c) OVER (ORDER BY month ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) = 3
                THEN AVG(receipts_c) OVER (ORDER BY month ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) END AS receipts_roll3,
           CASE WHEN COUNT(disposals_c) OVER (ORDER BY month ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) = 3
                THEN AVG(disposals_c) OVER (ORDER BY month ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) END AS disposals_roll3,
           CASE WHEN COUNT(pending_c) OVER (ORDER BY month ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) = 3
                THEN AVG(pending_c) OVER (ORDER BY month ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) END AS pending_roll3,
           published_receipts_roll3,
           published_disposals_roll3,
           published_pending_roll3
    FROM masked
)
SELECT month,
       has_partial_value,
       receipts_roll3,
       disposals_roll3,
       pending_roll3,
       ((ABS(receipts_roll3 - published_receipts_roll3) < 1e-6
         OR (receipts_roll3 IS NULL AND published_receipts_roll3 IS NULL))
        AND (ABS(disposals_roll3 - published_disposals_roll3) < 1e-6
         OR (disposals_roll3 IS NULL AND published_disposals_roll3 IS NULL))
        AND (ABS(pending_roll3 - published_pending_roll3) < 1e-6
         OR (pending_roll3 IS NULL AND published_pending_roll3 IS NULL))) AS matches_published
FROM rolled
ORDER BY month;

-- name: 04_first_last_appearance
-- 04_first_last_appearance.sql  (Redshift)
-- First and most recent appearance of each ministry in each published list type, with the report months
-- and the value printed at the latest appearance. Port of analysis B / repeated_listings (src/export/powerbi.py).
-- Lists are compared only within one list type (thresholds differ between types; dim_list.caveat), and
-- absence from a list is never read as zero.
-- in_latest_list: listed in the most recent report that published this list type.
-- Self-check: appearances and first/last report must equal the published repeated_listings row.
WITH appearances AS (
    SELECT la.list_code,
           la.ministry_id,
           la.report_number,
           dr.report_month,
           COALESCE(la.pending, la.pending_over_threshold, la.avg_closing_time_days) AS printed_value,
           ROW_NUMBER() OVER (PARTITION BY la.list_code, la.ministry_id ORDER BY la.report_number DESC) AS recency
    FROM gl.list_appearances la
    JOIN gl.dim_report dr ON dr.report_number = la.report_number
),
summary AS (
    SELECT list_code,
           ministry_id,
           COUNT(DISTINCT report_number) AS appearances,
           MIN(report_number) AS first_listed_report,
           MAX(report_number) AS last_listed_report,
           MIN(report_month) AS first_listed_month,
           MAX(report_month) AS last_listed_month,
           MAX(CASE WHEN recency = 1 THEN printed_value END) AS value_at_last_appearance
    FROM appearances
    GROUP BY list_code, ministry_id
)
SELECT s.list_code,
       s.ministry_id,
       d.canonical_name,
       s.appearances,
       s.first_listed_report,
       s.first_listed_month,
       s.last_listed_report,
       s.last_listed_month,
       s.value_at_last_appearance,
       l.value_measure,
       (s.last_listed_report = l.last_report) AS in_latest_list,
       (s.appearances = r.appearances
        AND s.first_listed_report = r.first_listed_report
        AND s.last_listed_report = r.last_listed_report) AS matches_published
FROM summary s
JOIN gl.dim_ministry d ON d.ministry_id = s.ministry_id
JOIN gl.dim_list l ON l.list_code = s.list_code
LEFT JOIN gl.repeated_listings r
       ON r.list_code = s.list_code AND r.ministry_id = s.ministry_id
ORDER BY s.list_code, s.appearances DESC, s.ministry_id;

-- name: 05_demand_vs_backlog
-- 05_demand_vs_backlog.sql  (Redshift)
-- Demand vs backlog per ministry: is intake (receipts) rising, and is the backlog (month-end pending) rising
-- faster or slower? Port of analysis G (src/analysis/analyses.py analysis_g, src/analysis/config.py):
--   * window: single-month flows #29-#45 (v_flow_panel); a ministry needs >= 15 gap-free consecutive reports,
--     otherwise 'insufficient months';
--   * mean monthly receipts >= 100 and mean pending >= 50, otherwise 'insufficient volume';
--   * trend size = Sen's slope (median of all pairwise slopes (y_j - y_i) / (j - i)), computed exactly here,
--     as a % of the series mean per month; |slope| < 1.0 %/month = 'stable' (STABLE_BAND_PCT_PER_MONTH).
-- The Mann-Kendall p/q-values of the original are not recomputed in SQL (autocorrelation-corrected variance);
-- they are descriptive only in the quadrant labels, which depend on the slopes and the band alone.
-- Self-check: status, both trend labels and the quadrant must equal demand_backlog_quadrants.
WITH panel AS (
    SELECT ministry_id, report_number, CAST(receipts AS DOUBLE PRECISION) AS receipts, CAST(pending AS DOUBLE PRECISION) AS pending
    FROM gl.v_flow_panel
),
per_ministry AS (
    SELECT ministry_id,
           COUNT(*) AS months,
           MAX(report_number) - MIN(report_number) + 1 AS span,
           AVG(receipts) AS mean_monthly_receipts,
           AVG(pending) AS mean_pending
    FROM panel
    GROUP BY ministry_id
),
eligible AS (
    SELECT m.*,
           CASE WHEN m.months < 15 OR m.span <> m.months THEN 'insufficient months'
                WHEN m.mean_monthly_receipts < 100 OR m.mean_pending < 50 THEN 'insufficient volume'
                ELSE 'classified' END AS status
    FROM per_ministry m
),
pair_slopes AS (
    SELECT a.ministry_id,
           (b.receipts - a.receipts) / (b.report_number - a.report_number) AS receipts_slope,
           (b.pending - a.pending) / (b.report_number - a.report_number) AS pending_slope
    FROM panel a
    JOIN panel b ON b.ministry_id = a.ministry_id AND b.report_number > a.report_number
    JOIN eligible e ON e.ministry_id = a.ministry_id AND e.status = 'classified'
),
ranked AS (
    SELECT ministry_id,
           receipts_slope,
           pending_slope,
           ROW_NUMBER() OVER (PARTITION BY ministry_id ORDER BY receipts_slope) AS r_rn,
           ROW_NUMBER() OVER (PARTITION BY ministry_id ORDER BY pending_slope) AS p_rn,
           COUNT(*) OVER (PARTITION BY ministry_id) AS pairs
    FROM pair_slopes
),
sen AS (
    -- exact median: the middle value, or the mean of the two middle values when the count is even
    SELECT ministry_id,
           AVG(CASE WHEN r_rn IN (FLOOR((pairs + 1) / 2.0), CEIL((pairs + 1) / 2.0)) THEN receipts_slope END)
               AS receipts_sen_slope,
           AVG(CASE WHEN p_rn IN (FLOOR((pairs + 1) / 2.0), CEIL((pairs + 1) / 2.0)) THEN pending_slope END)
               AS pending_sen_slope
    FROM ranked
    GROUP BY ministry_id
),
classified AS (
    SELECT e.ministry_id,
           e.months,
           e.mean_monthly_receipts,
           e.mean_pending,
           e.status,
           100 * s.receipts_sen_slope / e.mean_monthly_receipts AS demand_rel_slope_pct,
           100 * s.pending_sen_slope / e.mean_pending AS backlog_rel_slope_pct
    FROM eligible e
    LEFT JOIN sen s ON s.ministry_id = e.ministry_id
),
labelled AS (
    SELECT c.*,
           CASE WHEN c.status <> 'classified' THEN NULL
                WHEN c.demand_rel_slope_pct >= 1.0 THEN 'rising'
                WHEN c.demand_rel_slope_pct <= -1.0 THEN 'falling' ELSE 'stable' END AS demand_trend,
           CASE WHEN c.status <> 'classified' THEN NULL
                WHEN c.backlog_rel_slope_pct >= 1.0 THEN 'rising'
                WHEN c.backlog_rel_slope_pct <= -1.0 THEN 'falling' ELSE 'stable' END AS backlog_trend
    FROM classified c
)
SELECT l.ministry_id,
       d.canonical_name,
       l.months,
       l.mean_monthly_receipts,
       l.mean_pending,
       l.status,
       l.demand_rel_slope_pct,
       l.backlog_rel_slope_pct,
       l.demand_trend,
       l.backlog_trend,
       CASE WHEN l.status = 'classified'
            THEN 'demand ' || l.demand_trend || ' / backlog ' || l.backlog_trend END AS quadrant,
       (l.status = q.status
        AND (l.demand_trend = q.demand_trend OR (l.demand_trend IS NULL AND q.demand_trend IS NULL))
        AND (l.backlog_trend = q.backlog_trend OR (l.backlog_trend IS NULL AND q.backlog_trend IS NULL))
        AND (ABS(l.demand_rel_slope_pct - q.demand_rel_slope_pct) < 1e-9
             OR (l.demand_rel_slope_pct IS NULL AND q.demand_rel_slope_pct IS NULL))
        AND (ABS(l.backlog_rel_slope_pct - q.backlog_rel_slope_pct) < 1e-9
             OR (l.backlog_rel_slope_pct IS NULL AND q.backlog_rel_slope_pct IS NULL))) AS matches_published
FROM labelled l
JOIN gl.dim_ministry d ON d.ministry_id = l.ministry_id
LEFT JOIN gl.demand_backlog_quadrants q ON q.ministry_id = l.ministry_id
ORDER BY l.status, quadrant, l.ministry_id;
